import type { createAdmin } from "arky-sdk/admin";
import type { createStorefront } from "arky-sdk/storefront";
import type {
  StorefrontPromotion,
  GetStorefrontPromotionParams,
  CreatePromotionCodeParams,
  CreatePromotionParams,
  FindPromotionCodesParams,
  FindPromotionsParams,
  GetPromotionByKeyParams,
  GetPromotionCodeByCodeParams,
  PaginatedResponse,
  Promotion,
  PromotionCode,
  PromotionCodeWebhookPayload,
  PromotionEditableStatus,
  PromotionEffect,
  PromotionFixedScope,
  Money,
  Block,
  Schedule,
  PromotionCondition,
  PromotionActivation,
  PromotionLimit,
  PromotionStacking,
  PromotionStatus,
  PromotionTarget,
  PromotionWebhookPayload,
  ShippingRateCondition,
  UpdatePromotionParams,
  UpdatePromotionCodeParams,
  WebhookEventName,
} from "arky-sdk/types";

type Assert<T extends true> = T;
type Equal<A, B> = (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;
type Missing<T, K extends PropertyKey> = K extends keyof T ? false : true;
type RequiredField<T, K extends keyof T> = {} extends Pick<T, K> ? false : true;
type Eshop = ReturnType<typeof createAdmin>["eshop"];
type StorefrontEshop = ReturnType<typeof createStorefront>["eshop"];

export type PromotionContracts = [
  Assert<Equal<Parameters<Eshop["promotion"]["getByKey"]>[0], GetPromotionByKeyParams>>,
  Assert<Equal<Parameters<Eshop["promotionCode"]["getByCode"]>[0], GetPromotionCodeByCodeParams>>,
  Assert<Equal<Awaited<ReturnType<Eshop["promotion"]["find"]>>, PaginatedResponse<Promotion>>>,
  Assert<Equal<Awaited<ReturnType<Eshop["promotionCode"]["find"]>>, PaginatedResponse<PromotionCode>>>,
  Assert<Equal<Awaited<ReturnType<Eshop["promotion"]["delete"]>>, Promotion | undefined>>,
  Assert<Equal<Awaited<ReturnType<Eshop["promotionCode"]["delete"]>>, PromotionCode | undefined>>,
  Assert<Equal<NonNullable<FindPromotionsParams["status"]>, PromotionStatus["type"]>>,
  Assert<Equal<keyof FindPromotionCodesParams, "store_id" | "promotion_id" | "code" | "status" | "limit" | "cursor">>,
  Assert<RequiredField<CreatePromotionParams, "id">>,
  Assert<RequiredField<CreatePromotionParams, "blocks">>,
  Assert<Equal<CreatePromotionParams["blocks"], Block[]>>,
  Assert<RequiredField<CreatePromotionParams, "activation">>,
  Assert<Equal<CreatePromotionParams["activation"], PromotionActivation>>,
  Assert<Missing<UpdatePromotionParams, "activation">>,
  Assert<Equal<Promotion["activation"], PromotionActivation>>,
  Assert<Equal<PromotionActivation["type"], "codes" | "automatic">>,
  Assert<Equal<PromotionActivation, { type: "codes" } | { type: "automatic" }>>,
  Assert<Equal<PromotionLimit, { type: "unlimited" } | { type: "limited"; max_uses: number }>>,
  Assert<Equal<Promotion["limit"], PromotionLimit>>,
  Assert<Equal<PromotionCode["limit"], PromotionLimit>>,
  Assert<Equal<CreatePromotionParams["limit"], PromotionLimit>>,
  Assert<Equal<UpdatePromotionParams["limit"], PromotionLimit>>,
  Assert<Equal<CreatePromotionCodeParams["limit"], PromotionLimit>>,
  Assert<Equal<UpdatePromotionCodeParams["limit"], PromotionLimit>>,
  Assert<RequiredField<CreatePromotionParams, "limit">>,
  Assert<RequiredField<UpdatePromotionParams, "limit">>,
  Assert<RequiredField<CreatePromotionCodeParams, "limit">>,
  Assert<RequiredField<UpdatePromotionCodeParams, "limit">>,
  Assert<Equal<Promotion["customer_limit"], PromotionLimit>>,
  Assert<Equal<CreatePromotionParams["customer_limit"], PromotionLimit>>,
  Assert<Equal<UpdatePromotionParams["customer_limit"], PromotionLimit>>,
  Assert<Equal<PromotionWebhookPayload["customer_limit"], PromotionLimit>>,
  Assert<RequiredField<CreatePromotionParams, "customer_limit">>,
  Assert<RequiredField<UpdatePromotionParams, "customer_limit">>,
  Assert<Missing<Promotion, "max_uses_per_customer">>,
  Assert<Missing<CreatePromotionParams, "max_uses_per_customer">>,
  Assert<Missing<UpdatePromotionParams, "max_uses_per_customer">>,
  Assert<Missing<PromotionWebhookPayload, "max_uses_per_customer">>,
  Assert<Missing<PromotionCode, "customer_limit">>,
  Assert<Missing<Promotion, "max_uses">>,
  Assert<Missing<PromotionCode, "max_uses">>,
  Assert<Missing<CreatePromotionParams, "max_uses" | "uses">>,
  Assert<Missing<UpdatePromotionParams, "max_uses" | "uses">>,
  Assert<Missing<CreatePromotionCodeParams, "max_uses" | "uses">>,
  Assert<Missing<UpdatePromotionCodeParams, "max_uses" | "uses">>,
  Assert<Equal<Promotion["uses"], number>>,
  Assert<Equal<PromotionCode["uses"], number>>,
  Assert<Equal<PromotionWebhookPayload, Omit<Promotion, "uses">>>,
  Assert<Equal<PromotionCodeWebhookPayload, Omit<PromotionCode, "uses">>>,
  Assert<Missing<PromotionWebhookPayload, "uses" | "max_uses">>,
  Assert<Missing<PromotionCodeWebhookPayload, "uses" | "max_uses">>,
  Assert<Equal<PromotionWebhookPayload["limit"], PromotionLimit>>,
  Assert<Equal<PromotionCodeWebhookPayload["limit"], PromotionLimit>>,
  Assert<Equal<Extract<WebhookEventName, "promotion.uses_changed" | "promotion_code.uses_changed">, never>>,
  Assert<Equal<PromotionStacking["type"], "continue" | "stop_after">>,
  Assert<Equal<CreatePromotionParams["stacking"], PromotionStacking>>,
  Assert<Equal<UpdatePromotionParams["stacking"], PromotionStacking>>,
  Assert<Equal<Extract<PromotionTarget, { type: "product_variants" }>, { type: "product_variants"; variant_ids: string[] }>>,
  Assert<Equal<Extract<PromotionCondition, { type: "minimum_subtotal" }>, { type: "minimum_subtotal"; amounts: Money[] }>>,
  Assert<Equal<Extract<PromotionCondition, { type: "item_quantity" }>, { type: "item_quantity"; target: PromotionTarget; min_quantity: number; max_quantity: number | null }>>,
  Assert<Equal<PromotionCondition["type"], "signed_in" | "customer" | "customer_group" | "customer_group_offering" | "company" | "company_location" | "market" | "sales_channel" | "minimum_subtotal" | "item_quantity">>,
  Assert<Equal<Extract<PromotionEffect, { type: "item_fixed" }>["scope"], PromotionFixedScope>>,
  Assert<Equal<Extract<PromotionEffect, { type: "item_fixed" }>["amounts"], Money[]>>,
  Assert<Missing<Extract<PromotionEffect, { type: "item_fixed" }>, "money">>,
  Assert<RequiredField<CreatePromotionCodeParams, "id">>,
  Assert<Equal<CreatePromotionParams["status"], PromotionEditableStatus>>,
  Assert<Equal<Extract<PromotionStatus, { type: "deleting" }>, Exclude<PromotionStatus, PromotionEditableStatus>>>,
  Assert<Equal<CreatePromotionParams["schedule"], Schedule>>,
  Assert<Missing<CreatePromotionParams, "starts_at" | "ends_at">>,
  Assert<Equal<Schedule["type"], "always" | "scheduled">>,
  Assert<Equal<PromotionTarget["type"], "products" | "product_variants" | "booking_services" | "customer_group_offerings" | "customer_groups" | "catalogs" | "categories" | "all_eligible_items">>,
  Assert<Equal<Extract<PromotionTarget, { type: "customer_group_offerings" }>, { type: "customer_group_offerings"; customer_group_offering_ids: string[] }>>,
  Assert<Equal<Extract<PromotionTarget, { type: "customer_groups" }>, { type: "customer_groups"; customer_group_ids: string[] }>>,
  Assert<Equal<Extract<PromotionCondition, { type: "customer_group_offering" }>, { type: "customer_group_offering"; ids: string[] }>>,
  Assert<Equal<Extract<ShippingRateCondition, { type: "customer_group_offering" }>, { type: "customer_group_offering"; ids: string[] }>>,
  Assert<Equal<PromotionEffect["type"], "item_percentage" | "item_fixed" | "order_percentage" | "order_fixed" | "delivery_percentage" | "delivery_fixed" | "buy_x_get_y">>,
  Assert<Equal<StorefrontPromotion, { id: string; key: string; blocks: Block[] }>>,
  Assert<Equal<keyof StorefrontEshop["promotion"], "get">>,
  Assert<Equal<Parameters<StorefrontEshop["promotion"]["get"]>[0], GetStorefrontPromotionParams>>,
  Assert<Equal<keyof GetStorefrontPromotionParams, "id">>,
  Assert<Equal<Awaited<ReturnType<StorefrontEshop["promotion"]["get"]>>, StorefrontPromotion>>,
];
